#!/usr/bin/env python3
"""Arithmetic checks for seven-no-root D=-2,k=4,d=0,p=3 filters."""

N = 7
rank_p = 3
D = -2
p = 3
d = 0
k = 4
T_DIM = 15

# Previously proved generalized Hamming lower bounds for this branch.
ghw_lb = (3, 4, 6)

# Projective-system translation for a [n,3] code generated by a 3 x n matrix:
# d1 = n - max number of columns in a rank <=2 flat,
# d2 = n - max number of columns in a rank <=1 flat,
# d3 = n - number of zero columns.
max_rank2_flat = N - ghw_lb[0]
max_rank1_flat = N - ghw_lb[1]
max_zero_columns = N - ghw_lb[2]

assert (max_rank2_flat, max_rank1_flat, max_zero_columns) == (4, 3, 1)

# A local r-dimensional subcode L supported on S forces all columns outside S
# into a flat of rank at most rank(P)-r. Apply the flat-size caps.
min_support_rank1_local = N - max_rank2_flat
min_support_rank2_local = N - max_rank1_flat
assert min_support_rank1_local == 3
assert min_support_rank2_local == 4

# In the target branch the selected-row count is 7 + p + 3c and D=-2,
# so the relation rank is c+4. It lives in the 15-dimensional T-space.
# Hence c+4 <=15.
max_complete_blocks = T_DIM - 4
assert max_complete_blocks == 11

# Check the same relation-rank transport through all deletion depths using the
# already proved q_S caps for D=-2.
q_caps = (0, 0, 1, 2, 2, 3, 4)
for s, qmax in enumerate(q_caps, start=1):
    # D(B\S)=D+2s-3q >= 0 for every nonempty deletion.
    assert D + 2 * s - 3 * qmax >= 0
    assert qmax == (D + 2 * s) // 3

print("PASS: seven-no-root D=-2,k=4,d=0,p=3 projective/T-cap filters")
print("projective_flat_caps", {
    "rank<=2": max_rank2_flat,
    "rank<=1": max_rank1_flat,
    "zero_columns": max_zero_columns,
})
print("local_support_minima", {
    "rank1": min_support_rank1_local,
    "rank2": min_support_rank2_local,
})
print("max_complete_blocks", max_complete_blocks)
